def find_all_components(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    colors = {}

    def bfs(r, c, color):
        cells = [(r,c)]
        stack = [(r,c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
                    cells.append((nr, nc))
        return cells

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                comp = bfs(r, c, color)
                if color not in colors:
                    colors[color] = []
                colors[color].extend(comp)

    return colors

