def extract_shapes(grid):
    """Extract shapes in reading order"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    shapes = []

    def bfs(r, c):
        color = grid[r][c]
        stack = [(r,c)]
        visited[r][c] = True
        cells = []
        while stack:
            cr, cc = stack.pop()
            cells.append((cr, cc))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
        return color, cells

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                color, cells = bfs(r, c)
                rows = [x[0] for x in cells]
                cols = [x[1] for x in cells]
                height = max(rows)+1-min(rows)
                width = max(cols)+1-min(cols)
                shapes.append({
                    'color': color, 
                    'cells': cells,
                    'height': height, 
                    'width': width
                })
    return shapes

def pack_diagonally(shapes, h_out, w_out):
    """Pack shapes diagonally - see which cells might be lost"""
    out = [[0]*w_out for _ in range(h_out)]

    for i, shape in enumerate(shapes):
        # Start position - each shape starts one row lower and two columns righter
        start_r = i
        start_c = i*2

        # Try to place as many cells as possible
        for r_rel in range(shape['height']):
            for c_rel in range(shape['width']):
                new_r, new_c = start_r + r_rel, start_c + c_rel
                if new_r < h_out and new_c < w_out:
                    out[new_r][new_c] = shape['color']
                else:
                    print(f"Shape {i} ({shape['color']}): cell at ({new_r},{new_c}) OUT OF BOUNDS")
    return out

