def pack_from_tl(shapes):
    """Pack shapes as if they're falling down from the top-left corner"""
    h_out, w_out = 10, 10
    grid = [[0]*w_out for _ in range(h_out)]

    for shape in shapes:
        sr, sc = shape['min_r'], shape['min_c']
        sh, sw = shape['height'], shape['width']

        # Try to pack into first available position
        packed = False
        for tr in range(h_out):
            if packed:
                break
            for tc in range(w_out):
                # Check if we can fit
                ok = True
                for dr in range(sh):
                    for dc in range(sw):
                        if grid[tr+dr][tc+dc] != 0:
                            ok = False
                            break
                    if not ok:
                        break

                if ok:
                    # Place it
                    for dr in range(sh):
                        for dc in range(sw):
                            grid[tr+dr][tc+dc] = shape['color']
                    packed = True
                    break

    return grid

