    """Extract shapes preserving min_row, min_col, height, width"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    shapes = []

    def bfs(r, c):
        stack = [(r,c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                bfs(r, c)
                cells = []
                for rr in range(h):
                    for cc in range(w):
                        if visited[rr][cc]:
                            cells.append((rr, cc))

                rows = [x[0] for x in cells]
                cols = [x[1] for x in cells]

                shapes.append({
                    'color': grid[r][c],
                    'cells': cells,
                    'min_r': min(rows), 'max_r': max(rows),
                    'min_c': min(cols), 'max_c': max(cols),
                    'height': max(rows)-min(rows)+1,
                    'width': max(cols)-min(cols)+1
                })
    return shapes

def pack_from_tl(shapes):
    """Pack shapes as if they're falling down from the top-left corner"""
    h_out, w_out = 10, 10
    grid = [[0]*w_out for _ in range(h_out)]

    for shape in shapes:
        # Try to place at (0,0) or next available spot
        packed = False
        for tr in range(h_out):
            if packed:
                break
            for tc in range(w_out):
                ok = True
                sh, sw = shape['height'], shape['width']
                for dr in range(sh):
                    for dc in range(sw):
                        if tr+dr >= h_out or tc+dc >= w_out:
                            ok = False
                            break
                        if grid[tr+dr][tc+dc] != 0:
                            ok = False
                            break

                if ok:
                    for dr in range(sh):
                        for dc in range(sw):
                            grid[tr+dr][tc+dc] = shape['color']
                    packed = True
                    break

    return grid

